def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_row = next((i for i, row in enumerate(grid)
                    if len(set(row)) == 1 and all(row[0] not in other
                    for j, other in enumerate(grid) if j != i)), None)
    if sep_row is not None:
        a, b = grid[:sep_row], grid[sep_row + 1:]
    else:
        sep_col = next(j for j in range(w)
                       if len({grid[i][j] for i in range(h)}) == 1
                       and all(grid[i][j] not in row[:j] + row[j + 1:]
                               for row in grid))
        a = [row[:sep_col] for row in grid]
        b = [row[sep_col + 1:] for row in grid]
    shared = {x for row in a for x in row} & {x for row in b for x in row}
    base = max(shared, key=lambda c: sum(x == c for row in a for x in row)
                + sum(x == c for row in b for x in row))
    return [[3 if x == y else base for x, y in zip(ra, rb)]
            for ra, rb in zip(a, b)]
